BANKA = 32   # paylasimli bellek bankasi sayisi

def cakisma(adresler_kelime):
    # Ayni bankadaki FARKLI adres sayisi cakisma derecesidir;
    # ayni adres yayinlanir (broadcast), cakisma sayilmaz.
    kova = {}
    for a in adresler_kelime:
        kova.setdefault(a % BANKA, set()).add(a)
    return max(len(s) for s in kova.values()), len(kova)

