WARP = 32

def serilesme(hedefler):
    # ayni adrese giden atomik islemler siraya girer;
    # warp'in maliyeti en kalabalik hedefteki islem sayisidir
    sayac = {}
    for h in hedefler:
        sayac[h] = sayac.get(h, 0) + 1
    return max(sayac.values()), len(sayac)

