import math

def hillis_steele(n):
    is_, derinlik, ofset = 0, 0, 1
    while ofset < n:
        is_ += n - ofset      # ofset kadar is parcacigi bu adimda calismaz
        derinlik += 1
        ofset *= 2
    return is_, derinlik

def blelloch(n):
    # yukari-sup + asagi-sup: toplam 2(n-1) islem, derinlik 2*log2(n)
    return 2 * (n - 1), 2 * int(math.log2(n))

for n in (32, 256, 1024, 4096):
    hw, hd = hillis_steele(n)
    bw, bd = blelloch(n)
    print(f"n={n:5d} | HS is={hw:6d} derinlik={hd:2d} | Blelloch is={bw:5d} derinlik={bd:2d} | is orani={hw/bw:.3f}")

